// tests/home.spec.js
import { test, expect } from '@playwright/test';

test('homepage has correct title', async ({ page }) => {
  await page.goto('http://localhost:3000');
  await expect(page).toHaveTitle(/My Next.js App/);
  await expect(page.locator('h1')).toHaveText('Welcome');
});

// tests/feedback.spec.js
import { test, expect } from '@playwright/test';

test('submit feedback form', async ({ page }) => {
  await page.goto('http://localhost:3000/feedback');
  await page.fill('textarea[name="message"]', 'Great site!');
  await page.click('button[type="submit"]');
  await expect(page.locator('.success')).toHaveText('Thanks!');
});
